package com.example.blades360;

import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.util.AtomicFile;
import com.yausername.youtubedl_android.*;
import org.json.*;
import org.xmlpull.v1.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

/** Public YouTube extraction; subscriptions and libraries belong only to this device. */
final class YoutubeClient {
 static final String BUNDLED="2026.10.26";
 final MainActivity a;final SharedPreferences prefs;final ExecutorService worker=Executors.newSingleThreadExecutor(),artWorker=Executors.newFixedThreadPool(2);final ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();
 volatile String processId="";volatile int generation;volatile boolean closed;boolean busy,initialized;String status="Browse YouTube · no account required";Runnable changed=()->{};
 final android.util.LruCache<String,Bitmap> images=new android.util.LruCache<String,Bitmap>(12*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getByteCount();}};final Set<String> pending=new HashSet<>();
 YoutubeClient(MainActivity a){this(a,"youtube_local");}YoutubeClient(MainActivity a,String store){this.a=a;prefs=a.getSharedPreferences(store,0);}
 void notifyChanged(){if(!closed)changed.run();}
 static String input(String raw){try{Uri u=Uri.parse(raw.trim());String host=u.getHost();if(!"https".equals(u.getScheme())||u.getUserInfo()!=null||u.getPort()!=-1||host==null)return "";if(!Arrays.asList("youtube.com","www.youtube.com","m.youtube.com","music.youtube.com","youtu.be").contains(host.toLowerCase(Locale.ROOT)))return "";return u.toString();}catch(Exception e){return "";}}
 static String watch(String id){return id.matches("[A-Za-z0-9_-]{11}")?"https://www.youtube.com/watch?v="+id:"";}
 static String channelUrl(String id){return id.matches("UC[A-Za-z0-9_-]{22}")?"https://www.youtube.com/channel/"+id:"";}
 static JSONObject compact(JSONObject j){JSONObject out=new JSONObject();try{String id=j.optString("id");out.put("id",id).put("url",watch(id)).put("title",j.optString("title","Untitled video")).put("channel",j.optString("channel",j.optString("uploader",""))).put("channel_id",j.optString("channel_id")).put("channel_url",channelUrl(j.optString("channel_id"))).put("duration",j.optLong("duration")).put("timestamp",j.optLong("timestamp")).put("view_count",j.optLong("view_count"));String desc=j.isNull("description")?"":j.optString("description");if(desc.isEmpty())desc="Select to play, browse this channel, or save to your local library.";out.put("description",desc.substring(0,Math.min(3000,desc.length())));String thumb=j.optString("thumbnail");if(thumb.isEmpty()){JSONArray thumbs=j.optJSONArray("thumbnails");if(thumbs!=null&&thumbs.length()>0)thumb=thumbs.optJSONObject(thumbs.length()-1).optString("url");}out.put("thumbnail",thumb);}catch(Exception ignored){}return out;}
 JSONArray list(String name){try{return new JSONArray(prefs.getString(name,"[]"));}catch(Exception e){return new JSONArray();}}
 boolean contains(String name,String id){JSONArray rows=list(name);for(int i=0;i<rows.length();i++)if(rows.optJSONObject(i)!=null&&rows.optJSONObject(i).optString("id").equals(id))return true;return false;}
 void save(String name,JSONObject item,boolean remove){JSONArray old=list(name),out=new JSONArray();if(!remove)out.put(item);for(int i=0;i<old.length()&&out.length()<500;i++){JSONObject row=old.optJSONObject(i);if(row!=null&&!row.optString("id").equals(item.optString("id")))out.put(row);}prefs.edit().putString(name,out.toString()).apply();notifyChanged();}
 void toggle(String name,JSONObject item){save(name,item,contains(name,item.optString("id")));}
 void enqueue(JSONObject item){JSONArray out=list("queue");if(out.length()>=100){status="Queue is full (100 videos)";notifyChanged();return;}out.put(item);prefs.edit().putString("queue",out.toString()).apply();notifyChanged();}
 void removeQueued(String id){JSONArray old=list("queue"),out=new JSONArray();boolean removed=false;for(int i=0;i<old.length();i++){JSONObject row=old.optJSONObject(i);if(row==null)continue;if(!removed&&row.optString("id").equals(id)){removed=true;continue;}out.put(row);}prefs.edit().putString("queue",out.toString()).apply();notifyChanged();}
 JSONObject popQueue(){JSONArray old=list("queue"),out=new JSONArray();JSONObject first=old.optJSONObject(0);for(int i=1;i<old.length();i++)out.put(old.opt(i));prefs.edit().putString("queue",out.toString()).apply();return first;}
 void subscription(JSONObject video){String id=video.optString("channel_id");if(channelUrl(id).isEmpty()){status="Open a video first to resolve its channel";notifyChanged();return;}try{toggle("subscriptions",new JSONObject().put("id",id).put("title",video.optString("channel")).put("url",channelUrl(id)));}catch(Exception ignored){}}
 void history(JSONObject item,long position){try{JSONObject copy=new JSONObject(item.toString());copy.put("position",Math.max(0,position));copy.put("watched",System.currentTimeMillis());save("history",copy,false);}catch(Exception ignored){}}
 long position(String id){JSONArray rows=list("history");for(int i=0;i<rows.length();i++){JSONObject j=rows.optJSONObject(i);if(j!=null&&j.optString("id").equals(id))return j.optLong("position");}return 0;}
 void clear(String key){prefs.edit().remove(key).apply();notifyChanged();}
 void ensure()throws Exception{if(initialized)return;YoutubeDL.getInstance().init(a);if(prefs.getString("engine_version","").compareTo(BUNDLED)<0){try(InputStream in=a.getAssets().open("youtube/yt-dlp")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[16384];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);install(out.toByteArray());prefs.edit().putString("engine_version",BUNDLED).apply();}}initialized=true;}
 void install(byte[] bytes)throws Exception{File dir=new File(a.getNoBackupFilesDir(),"youtubedl-android/yt-dlp");dir.mkdirs();AtomicFile file=new AtomicFile(new File(dir,"yt-dlp"));FileOutputStream out=file.startWrite();try{out.write(bytes);file.finishWrite(out);}catch(Exception e){file.failWrite(out);throw e;}}
 YoutubeDLRequest request(String url){YoutubeDLRequest r=new YoutubeDLRequest(url);r.addOption("--ignore-config").addOption("--no-warnings").addOption("--skip-download").addOption("--socket-timeout","12").addOption("--retries","1").addOption("--extractor-retries","1");return r;}
 String execute(YoutubeDLRequest request,int ticket)throws Exception{ensure();if(ticket!=generation)throw new InterruptedException();String id="youtube-"+UUID.randomUUID();processId=id;ScheduledFuture<?> deadline=timer.schedule(()->YoutubeDL.getInstance().destroyProcessById(id),75,TimeUnit.SECONDS);try{return YoutubeDL.getInstance().execute(request,id,null).getOut();}finally{deadline.cancel(false);if(processId.equals(id))processId="";}}
 void cancel(){generation++;String id=processId;if(!id.isEmpty())YoutubeDL.getInstance().destroyProcessById(id);busy=false;}
 interface Task{Object run(int ticket)throws Exception;}
 void task(String message,Task task,Consumer<Object> result){cancel();int ticket=generation;busy=true;status=message;notifyChanged();worker.execute(()->{try{Object value=task.run(ticket);a.runOnUiThread(()->{if(closed||ticket!=generation)return;busy=false;status="Ready · local subscriptions and libraries";result.accept(value);notifyChanged();});}catch(Exception e){String messageText=e.getMessage()==null?"":e.getMessage().toLowerCase(Locale.ROOT);String safe=messageText.contains("sign in")||messageText.contains("login")?"YouTube requires sign-in for this request. This app does not sign in.":messageText.contains("private")||messageText.contains("unavailable")?"This video is unavailable or private.":"YouTube request failed. Check your connection or update yt-dlp in Settings.";a.runOnUiThread(()->{if(closed||ticket!=generation)return;busy=false;status=safe;notifyChanged();});}});}
 void browse(String source,int page,Consumer<JSONArray> done){task("Loading YouTube…",ticket->{String target=source.startsWith("search:")?"ytsearch"+((page+1)*20)+":"+source.substring(7):input(source);if(target.isEmpty())throw new IOException();YoutubeDLRequest r=request(target);r.addOption("--flat-playlist").addOption("--dump-single-json").addOption("--playlist-start",page*20+1).addOption("--playlist-end",page*20+20);JSONObject root=new JSONObject(execute(r,ticket));JSONArray entries=root.optJSONArray("entries"),out=new JSONArray();if(entries==null){JSONObject item=compact(root);if(!item.optString("url").isEmpty())out.put(item);}else for(int i=0;i<entries.length();i++){JSONObject j=entries.optJSONObject(i);if(j==null)continue;JSONObject item=compact(j);if(!item.optString("url").isEmpty())out.put(item);}return out;},value->done.accept((JSONArray)value));}
 void resolve(JSONObject item,boolean comments,Consumer<JSONObject> done){task(comments?"Loading public comments…":"Preparing video…",ticket->{String url=input(item.optString("url",watch(item.optString("id"))));if(url.isEmpty())throw new IOException();YoutubeDLRequest r=request(url);r.addOption("--no-playlist").addOption("--dump-single-json");int cap=prefs.getInt("quality",1080);r.addOption("-f","bv*[height<="+cap+"]+ba/b[height<="+cap+"]/b");if(comments){r.addOption("--write-comments").addOption("--extractor-args","youtube:max_comments=30,all,all,all;comment_sort=top");}return new JSONObject(execute(r,ticket));},value->done.accept((JSONObject)value));}
 void feed(Consumer<JSONArray> done){JSONArray subscriptions=list("subscriptions");task("Loading subscription feed…",ticket->{ArrayList<JSONObject> items=new ArrayList<>();int failed=0;for(int n=0;n<subscriptions.length();n++){if(ticket!=generation)throw new InterruptedException();JSONObject sub=subscriptions.optJSONObject(n);String id=sub.optString("id");if(channelUrl(id).isEmpty())continue;try{byte[] data=MediaHttp.get("https://www.youtube.com/feeds/videos.xml?channel_id="+id,Collections.emptyMap(),1024*1024);XmlPullParser p=XmlPullParserFactory.newInstance().newPullParser();p.setInput(new ByteArrayInputStream(data),"UTF-8");JSONObject item=null;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("entry"))item=new JSONObject().put("channel_id",id).put("channel",sub.optString("title"));else if(item!=null){if(tag.equals("yt:videoId"))item.put("id",p.nextText());else if(tag.equals("title"))item.put("title",p.nextText());else if(tag.equals("published"))item.put("timestamp",java.time.Instant.parse(p.nextText()).getEpochSecond());else if(tag.equals("media:thumbnail"))item.put("thumbnail",p.getAttributeValue(null,"url"));}}else if(event==XmlPullParser.END_TAG&&p.getName().equals("entry")&&item!=null){items.add(compact(item));item=null;}}}catch(Exception e){try{if(ticket!=generation)throw new InterruptedException();YoutubeDLRequest request=request(channelUrl(id)+"/videos");request.addOption("--flat-playlist").addOption("--dump-single-json").addOption("--playlist-end",5);JSONObject root=new JSONObject(execute(request,ticket));JSONArray videos=root.optJSONArray("entries");if(videos==null)throw new IOException();for(int i=0;i<videos.length();i++){JSONObject video=videos.optJSONObject(i);if(video!=null){JSONObject entry=compact(video);if(!entry.optString("url").isEmpty())items.add(entry);}}}catch(Exception ignored){failed++;}}}if(failed==subscriptions.length()&&failed>0)throw new IOException();items.sort((x,y)->Long.compare(y.optLong("timestamp"),x.optLong("timestamp")));JSONArray rows=new JSONArray();for(JSONObject item:items)rows.put(item);return rows;},value->done.accept((JSONArray)value));}
 void update(){task("Checking latest stable yt-dlp…",ticket->{ensure();JSONObject release=new JSONObject(new String(MediaHttp.get("https://api.github.com/repos/yt-dlp/yt-dlp/releases/latest",Collections.singletonMap("Accept","application/vnd.github+json"),1024*1024),StandardCharsets.UTF_8));String version=release.getString("tag_name");if(version.equals(prefs.getString("engine_version","")))return version;JSONArray assets=release.getJSONArray("assets");for(int i=0;i<assets.length();i++){JSONObject asset=assets.getJSONObject(i);if(!asset.optString("name").equals("yt-dlp"))continue;String url=asset.getString("browser_download_url"),digest=asset.optString("digest");if(!url.startsWith("https://github.com/yt-dlp/yt-dlp/releases/download/")||!digest.startsWith("sha256:"))throw new IOException();byte[] data=MediaHttp.get(url,Collections.emptyMap(),8*1024*1024);StringBuilder hash=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(data))hash.append(String.format(Locale.ROOT,"%02x",v));if(!digest.equals("sha256:"+hash)||ticket!=generation)throw new IOException();install(data);prefs.edit().putString("engine_version",version).apply();return version;}throw new IOException();},value->{status="yt-dlp "+value+" is installed";});}
 Bitmap image(String url){if(url==null||url.isEmpty()||closed)return null;Uri uri=Uri.parse(url);String host=uri.getHost();if(!"https".equals(uri.getScheme())||host==null||!(host.endsWith(".ytimg.com")||host.endsWith(".ggpht.com")||host.endsWith(".googleusercontent.com")))return null;Bitmap bitmap=images.get(url);if(bitmap!=null||pending.contains(url))return bitmap;pending.add(url);artWorker.execute(()->{Bitmap result=null;try{byte[] data=MediaHttp.get(url,Collections.emptyMap(),2*1024*1024);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,o);o.inSampleSize=1;while(o.outWidth/o.inSampleSize>640)o.inSampleSize*=2;o.inJustDecodeBounds=false;result=BitmapFactory.decodeByteArray(data,0,data.length,o);}catch(Exception ignored){}Bitmap loaded=result;a.runOnUiThread(()->{if(closed)return;if(loaded!=null)images.put(url,loaded);notifyChanged();});});return null;}
 void close(){closed=true;cancel();worker.shutdownNow();artWorker.shutdownNow();timer.shutdownNow();images.evictAll();}
}
